/**
 * Author contact: the QQ feedback group linked from the library top bar.
 * The QR is inlined so the client needs no extra static asset route.
 */

var CONTACT_QQ_GROUP = {
  name: 'dsh-music-panel反馈群',
  number: '495049439',
  qr: 'data:image/webp;base64,',
}

function P3ContactDialog(props) {
  return h(
    KitModal,
    { title: t('contact.title'), small: true, onClose: props.onClose },
    h(
      'div',
      { className: 'mpv3-contact' },
      h('img', {
        className: 'mpv3-contact-qr',
        src: CONTACT_QQ_GROUP.qr,
        alt: t('contact.qrAlt'),
        draggable: false,
      }),
      h('div', { className: 'mpv3-contact-name' }, CONTACT_QQ_GROUP.name),
      h('div', { className: 'mpv3-contact-number' }, t('contact.groupNumber', { number: CONTACT_QQ_GROUP.number })),
      h('p', { className: 'mpv3-contact-hint' }, t('contact.hint')),
      h(
        Button,
        {
          variant: 'ghost',
          onClick: function () {
            copyTextSafely(CONTACT_QQ_GROUP.number)
            showToast(t('contact.numberCopied'))
          },
        },
        t('contact.copyNumber'),
      ),
    ),
  )
}
